def sat(x, k, kind):
    from scipy.special import erf
    if kind == 'T':
        return np.tanh(k * x)
    if kind == 'A':
        return np.arctan(k * x)
    if kind == 'S':
        return x / np.sqrt(1 + k * x * x)
    if kind == 'R':
        return x / (1 + k * x * x)
    if kind == 'E':
        return erf(k * x)
    return x / (1 + k * abs(x))

def design(X, j, k, m):
    (t, u) = (X[:, j], X[:, (j + 2) % 4])
    v = t + k[2] * u
    h = k[1]
    f = sat(v, k[0], m[0])
    A = [np.ones(len(t)), f, u, t, u * u, t * t]
    extra = {'a': [abs(u), abs(t)], 'r': [u / (1 + h * u * u), u * u / (1 + h * u * u)], 't': [np.tanh(h * u), np.tanh(h * u) ** 2], 'p': [v ** 3 / (1 + h * v * v), u ** 3 / (1 + h * u * u)], 'q': [u * u * t, u * t * t], 's': [sat(t, h, m[0]), sat(u, h, m[0])], 'm': [t * u, t * t * t, u * u * u], 'b': [np.sin(h * u), np.cos(h * u)], 'd': [np.sin(h * u), np.sin(h * t)], 'h': [v ** 2 / (1 + h * v * v), u * u / (1 + h * u * u)], 'w': [t / (1 + h * t * t), u / (1 + h * u * u)]}
    for key in m[1:]:
        A += extra[key]
    return np.column_stack(A)

def fit(X, Y, j, m):
    from scipy.optimize import least_squares

    def resid(k, coeff=False):
        A = design(X, j, k, m)
        p = np.linalg.lstsq(A, Y[:, j], rcond=1e-09)[0]
        return p if coeff else A @ p - Y[:, j]
    start = [[1, 1, c] for c in (0, -0.18, 0.18)]
    best = min((least_squares(resid, k, bounds=([0.03, 0.03, -0.8], [8, 10, 0.8]), max_nfev=100, gtol=1e-10) for k in start), key=lambda r: r.cost)
    return (best.x, resid(best.x, True))
